var (
	appUserDBTypes = map[string]string{`ID`: `uuid`, `Email`: `character varying`, `FullName`: `character varying`, `AccountTypeRoleID`: `integer`, `AccountID`: `uuid`, `CreatedAt`: `timestamp without time zone`, `UpdatedAt`: `timestamp without time zone`}
	_              = bytes.MinRead
)

func testAppUsersUpdate(t *testing.T) {
	t.Parallel()

	if 0 == len(appUserPrimaryKeyColumns) {
		t.Skip("Skipping table with no primary key columns")
	}
	if len(appUserAllColumns) == len(appUserPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &AppUser{}
	if err = randomize.Struct(seed, o, appUserDBTypes, true, appUserColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize AppUser struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := AppUsers().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, appUserDBTypes, true, appUserPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize AppUser struct: %s", err)
	}

	if rowsAff, err := o.Update(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("should only affect one row but affected", rowsAff)
	}
}

func testAppUsersSliceUpdateAll(t *testing.T) {
	t.Parallel()

	if len(appUserAllColumns) == len(appUserPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &AppUser{}
	if err = randomize.Struct(seed, o, appUserDBTypes, true, appUserColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize AppUser struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := AppUsers().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, appUserDBTypes, true, appUserPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize AppUser struct: %s", err)
	}

	// Remove Primary keys and unique columns from what we plan to update
	var fields []string
	if strmangle.StringSliceMatch(appUserAllColumns, appUserPrimaryKeyColumns) {
		fields = appUserAllColumns
	} else {
		fields = strmangle.SetComplement(
			appUserAllColumns,
			appUserPrimaryKeyColumns,
		)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	typ := reflect.TypeOf(o).Elem()
	n := typ.NumField()

	updateMap := M{}
	for _, col := range fields {
		for i := 0; i < n; i++ {
			f := typ.Field(i)
			if f.Tag.Get("boil") == col {
				updateMap[col] = value.Field(i).Interface()
			}
		}
	}

	slice := AppUserSlice{o}
	if rowsAff, err := slice.UpdateAll(ctx, tx, updateMap); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("wanted one record updated but got", rowsAff)
	}
}

func testAppUsersUpsert(t *testing.T) {
	t.Parallel()

	if len(appUserAllColumns) == len(appUserPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	// Attempt the INSERT side of an UPSERT
	o := AppUser{}
	if err = randomize.Struct(seed, &o, appUserDBTypes, true); err != nil {
		t.Errorf("Unable to randomize AppUser struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Upsert(ctx, tx, false, nil, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert AppUser: %s", err)
	}

	count, err := AppUsers().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}

	// Attempt the UPDATE side of an UPSERT
	if err = randomize.Struct(seed, &o, appUserDBTypes, false, appUserPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize AppUser struct: %s", err)
	}

	if err = o.Upsert(ctx, tx, true, nil, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert AppUser: %s", err)
	}

	count, err = AppUsers().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}
}
